      "dest": "/etc/rancher/k3s/config.yaml",
      "mode": "0600"
    },
    "name": "Write protected cluster configuration",
    "no_log": true,
    "register": "cluster_config"
  },
  {
    "ansible.builtin.copy": {
      "content": "1d025d660a14474ad873\n",
      "dest": "/etc/rancher/k3s/bromigos-1d025d660a14474ad873",
      "mode": "0600"
    },
    "name": "Mark cluster ownership"
  },
  {
    "ansible.builtin.get_url": {
      "dest": "/opt/bromigos-k3s-install.sh",
      "mode": "0700",
      "url": "https://get.k3s.io"
    },
    "name": "Download k3s installer"
  },
  {
    "ansible.builtin.command": {
      "argv": [
        "/opt/bromigos-k3s-install.sh",
        "server"
      ],
      "creates": "/etc/systemd/system/k3s.service"
    },
    "environment": {
      "INSTALL_K3S_SKIP_START": "true",
      "INSTALL_K3S_VERSION": "v1.37.1+k3s1"
    },
    "name": "Install pinned k3s node",
    "no_log": true
  },
  {
    "ansible.builtin.systemd": {
      "enabled": true,
      "name": "k3s",
      "state": "{{ \"restarted\" if cluster_config.changed else \"started\" }}"
    },
    "name": "Keep cluster node running"
  },
  {
    "ansible.builtin.copy": {
      "content": "\"\"\"Wait for k3s bootstrap CRDs without changing their readiness or deleting data.\"\"\"\nimport json\nfrom pathlib import Path\nimport subprocess\nimport sys\nimport time\n\nNAMES = ('addons.k3s.cattle.io', 'etcdsnapshotfiles.k3s.cattle.io',\n         'helmchartconfigs.helm.cattle.io', 'helmcharts.helm.cattle.io')\n\n\ndef reconcile(run=subprocess.run, clock=time.monotonic, sleep=time.sleep, timeout=180):\n    started = clock()\n    requested = set()\n    while clock() - started < timeout:\n        result = run(['/usr/local/bin/k3s', 'kubectl', 'get', 'crds', '-o', 'json'],\n                     capture_output=True, text=True, timeout=15)\n        if result.returncode == 0:\n            rows = {r['metadata']['name']: r for r in json.loads(result.stdout)['items']}\n            conditions = {name: {c['type']: c['status'] for c in rows.get(name, {}).get('status', {}).get('conditions', [])} for name in NAMES}\n            if all(conditions[name].get('Established') == 'True' for name in NAMES):\n                return bool(requested)\n            if clock() - started >= 30:\n                for name in NAMES:\n                    if name not in requested and conditions[name].get('NamesAccepted') == 'True' and conditions[name].get('Established') == 'False':\n                        update = run(['/usr/local/bin/k3s', 'kubectl', 'annotate', 'crd', name,\n                                      'bromigos.org/bootstrap-reconcile=true', '--overwrite'],\n                                     capture_output=True, text=True, timeout=15)\n                        if update.returncode == 0: requested.add(name)\n        sleep(2)\n    raise RuntimeError('k3s bootstrap definitions did not become ready within three minutes')\n\n\nif __name__ == '__main__':\n    marker = Path(sys.argv[1])\n    if marker.parent != Path('/etc/rancher/k3s') or not marker.name.startswith('bromigos-') or not marker.is_file():\n        raise SystemExit('Refusing bootstrap changes on an unowned k3s installation')\n    try:\n        print('bootstrap-reconciled' if reconcile() else 'bootstrap-ready')\n    except (RuntimeError, OSError, ValueError, subprocess.TimeoutExpired):\n        raise SystemExit('k3s bootstrap check failed; inspect the owned cluster before retrying') from None\n",
      "dest": "/opt/bromigos-k3s-bootstrap.py",
      "mode": "0700"
    },
    "name": "Write bounded k3s bootstrap check"
  },
  {
    "ansible.builtin.command": {
      "argv": [
        "python3",
        "/opt/bromigos-k3s-bootstrap.py",
        "/etc/rancher/k3s/bromigos-1d025d660a14474ad873"
      ]
    },
    "changed_when": "'bootstrap-reconciled' in bootstrap_result.stdout",
    "name": "Wait for owned k3s bootstrap definitions",
    "register": "bootstrap_result"
  },
  {
    "ansible.builtin.command": {
      "argv": [
        "k3s",
        "kubectl",
        "wait",
        "--for=condition=Ready",
        "node/control",
        "--timeout=300s"
      ]
    },
    "changed_when": false,
    "name": "Wait for control plane"
  }
]

